manifest_content:
{
  "name": "open-generative-ai",
  "description": "Open-source alternative to HF AI — AI image, video, cinema and lip sync studio",
  "homepage": "https://github.com/Anil-matcha/Open-Generative-AI",
  "private": true,
  "version": "2.0.0",
  "license": "MIT",
  "workspaces": [
    "packages/studio",
    "packages/Vibe-Workflow/packages/workflow-builder",
    "packages/Open-Poe-AI/packages/agents",
    "packages/Open-AI-Design-Agent/packages/design-agent"
  ],
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start",
    "lint": "next lint",
    "build:studio": "npm run build -w studio",
    "build:workflow": "npm run build -w workflow-builder",
    "build:agent": "npm run build -w ai-agent",
    "build:design": "npm run build -w design-agent",
    "build:packages": "npm run build:workflow && npm run build:agent && npm run build:design && npm run build:studio",
    "setup": "git submodule update --init --recursive && npm install && npm run build:packages",
    "vite:dev": "vite",
    "vite:build": "vite build",
    "electron:dev": "npm run vite:build && electron .",
    "electron:build": "vite build && electron-builder --mac",
    "electron:build:win": "vite build && electron-builder --win",
    "electron:build:linux": "vite build && electron-builder --linux",
    "electron:build:linux:dir": "vite build && electron-builder --linux dir",
    "electron:build:linux:arm64:dir": "vite build && electron-builder --linux dir --arm64",
    "stage:local-ai": "node scripts/stage-local-ai-binary.js",
    "package:linux:deb": "node scripts/package-linux-deb.js",
    "package:linux:deb:arm64": "node scripts/package-linux-deb.js --arch arm64",
    "package:linux:deb:x64": "node scripts/package-linux-deb.js --arch x64",
    "electron:build:all": "vite build && electron-builder --mac --win --linux"
  },
  "build": {
    "appId": "ai.generative.open",
    "productName": "Open Generative AI",
    "copyright": "Copyright © 2025",
    "directories": {
      "output": "release"
    },
    "afterPack": "./afterPack.js",
    "files": [
      "dist/**/*",
      "electron/**/*"
    ],
    "extraResources": [
      {
        "from": "build/local-ai",
        "to": "local-ai",
        "filter": [
          "**/*"
        ]
      }
    ],
    "mac": {
      "category": "public.app-category.graphics-design",
      "icon": "public/banner.png",
      "gatekeeperAssess": false,
      "target": [
        {
          "target": "dmg",
          "arch": [
            "x64",
            "arm64"
          ]
        }
      ]
    },
    "win": {
      "icon": "public/banner.png",
      "signAndEditExecutable": false,
      "target": [
        {
          "target": "nsis",
          "arch": [
            "x64"
          ]
        }
      ]
    },
    "nsis": {
      "oneClick": false,
      "allowToChangeInstallationDirectory": true,
      "include": "build/installer.nsh"
    },
    "linux": {
      "icon": "public/banner.png",
      "category": "Utility",
      "maintainer": "Open Generative AI Team",
      "extraFiles": [
        {
          "from": "build/linux/apparmor.profile",
          "to": "resources/apparmor.profile"
        }
      ],
      "target": [
        {
          "target": "AppImage",
          "arch": [
            "x64"
          ]
        },
        {
          "target": "deb",
          "arch": [
            "x64"
          ]
        }
      ]
    }
  },
  "dependencies": {
    "ai-agent": "file:./packages/Open-Poe-AI/packages/agents",
    "axios": "^1.7.0",
    "next": "^15.0.0",
    "react": "^19.0.0",
    "react-dom": "^19.0.0",
    "react-hot-toast": "^2.4.1",
    "studio": "*",
    "workflow-builder": "file:./packages/Vibe-Workflow/packages/workflow-builder",
    "xtend": "^4.0.2"
  },
  "devDependencies": {
    "@eslint/eslintrc": "^3",
    "@tailwindcss/vite": "^4.1.18",
    "autoprefixer": "^10.4.24",
    "electron": "^33.4.11",
    "electron-builder": "^25.1.8",
    "eslint": "^9",
    "eslint-config-next": "^15.0.0",
    "postcss": "^8.5.6",
    "tailwindcss": "^3.4.0",
    "vite": "^5.4.0"
  },
  "main": "electron/main.js"
}

{
  "name": "opencti",
  "type": "module",
  "private": true,
  "workspaces": [
    "opencti-platform/eslint-plugin-custom-rules",
    "opencti-platform/opencti-front",
    "opencti-platform/opencti-graphql"
  ],
  "packageManager": "yarn@4.18.1+sha512.b2e1e7524f654f2749d32b4ebcb4622473cb5bcbc485df2007e12a154e50162a4d795526768bc5f5b8f81717bfd79deb2472813d86fb5ae2eb551fa9c872b08f",
  "engines": {
    "node": ">= 22.18.0"
  },
  "scripts": {
    "deps": "nx run-many --tuiAutoExit --target install",
    "dev": "nx run-many --target dev",
    "dev:watch": "nx run-many --target dev:watch",
    "dev:watch-with-graphql": "nx run-many --tuiAutoExit --target dev:watch-with-graphql",
    "build": "nx run-many --tuiAutoExit --target build",
    "test": "nx run-many --tuiAutoExit --target test,e2e",
    "lint": "nx run-many --tuiAutoExit --target lint",
    "graphql": "nx run-many --tuiAutoExit --target graphql",
    "with-python-venv": "node scripts/with_python_virtual_env.mjs",
    "deps:venv": "yarn with-python-venv yarn deps",
    "build:venv": "yarn with-python-venv yarn build",
    "dev:venv": "yarn with-python-venv yarn dev",
    "dev:watch:venv": "yarn with-python-venv yarn dev:watch",
    "dev:watch-with-graphql:venv": "yarn with-python-venv yarn dev:watch-with-graphql",
    "test:venv": "yarn with-python-venv yarn test",
    "build:ubi9": "nx run-many --tuiAutoExit --target build-ubi9",
    "push:ubi9": "nx run-many --tuiAutoExit --target push-ubi9",
    "renovate:dry-run": "LOG_LEVEL=debug yarn dlx renovate --dry-run --platform=local"
  },
  "devDependencies": {
    "nx": "24.0.4"
  },
  "resolutions": {
    "@filigran/chatbot/lodash": "4.18.1",
    "@filigran/chatbot/uuid": "14.0.3",
    "@types/pdfmake": "0.3.3",
    "axios": "1.21.0",
    "chokidar": "6.0.0",
    "d3-color": "3.1.1",
    "graphql": "patch:graphql@17.0.2#./patch/graphql-17.patch",
    "ioredis": "5.11.1",
    "json5": "2.2.3",
    "ldap-filter": "patch:ldap-filter@0.3.3#./patch/ldap-filter-0.3.3.patch",
    "monaco-editor/dompurify": "3.4.17",
    "openid-clientv5": "patch:openid-client@5.7.1#./patch/openid-client.patch",
    "openid-clientv5/jose": "5.10.0",
    "react-relay": "patch:react-relay@21.0.1#./patch/react-relay.patch"
  },
  "dependenciesMeta": {
    "@apollo/protobufjs": {
      "built": false
    },
    "@datadog/pprof": {
      "built": false
    },
    "core-js": {
      "built": false
    },
    "esbuild": {
      "built": false
    },
    "node-calls-python": {
      "built": true
    },
    "nx": {
      "built": false
    },
    "protobufjs": {
      "built": false
    },
    "re2": {
      "built": true
    },
    "unrs-resolver": {
      "built": false
    }
  }
}
